INSERT INTO cards (id,name,card_type,cost,attack,health,text,rarity,effect_id,effect_config,status) VALUES
('epic-spell-execution','처형','TECHNIQUE',5,0,0,'상대 선수 1장을 선택하여 DESTROY합니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"SELECT","id":"chosen","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"EFFECT","effect":{"action":"DESTROY","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"chosen"}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-feast','만찬','TECHNIQUE',4,0,0,'모든 아군 선수에게 HP +3을 부여합니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"EFFECT","effect":{"action":"BUFF","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1},"values":{"health":3}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-veil-of-silence','침묵의 장막','TECHNIQUE',5,0,0,'모든 상대 선수를 침묵시킵니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"EFFECT","effect":{"action":"SILENCE","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-return','복귀','TECHNIQUE',3,0,0,'내 무덤의 선수 중 무작위로 최대 3장을 선발합니다. 그중 1장을 선택하여 원래 상태로 내 덱에 넣습니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"SELECT","id":"candidates","target":{"zone":"GRAVEYARD","owner":"SELF","cardType":"WRESTLER","selection":"RANDOM","count":3,"randomScope":"FULL"}},{"type":"SELECT","id":"chosen","target":{"zone":"GRAVEYARD","owner":"SELF","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1,"resultId":"candidates"}},{"type":"EFFECT","effect":{"action":"MOVE_TO_DECK","target":{"zone":"GRAVEYARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"chosen"}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-forbidden-contract','금지된 계약','TECHNIQUE',4,0,0,'내 챔피언에게 5 피해를 줍니다. 이번 턴 다음에 사용하는 선수 카드 1장의 비용을 0으로 만듭니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"EFFECT","effect":{"action":"DAMAGE","target":{"zone":"PLAYER","owner":"SELF","selection":"ALL","count":1},"values":{"amount":5}}},{"type":"EFFECT","effect":{"action":"QUEUE_EFFECT","values":{"duration":"THIS_TURN","queuedTrigger":"NEXT_ALLY_WRESTLER_PLAYED","queuedEffect":{"action":"SET_STAT","target":{"zone":"HAND","owner":"SELF","cardType":"WRESTLER","selection":"SELF","count":1},"values":{"stat":"COST","amount":0}}}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-life-exchange','생명의 교환','TECHNIQUE',4,0,0,'아군 선수 1장과 상대 선수 1장을 선택하여 현재 HP를 서로 교환합니다. 기존 최대 HP 상한을 적용하며, 두 선수 모두 기절합니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"SELECT","id":"ally","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"SELECT","id":"enemy","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"AGGREGATE","id":"allyStat","selectionId":"ally","operation":"SUM","stat":"HEALTH"},{"type":"AGGREGATE","id":"enemyStat","selectionId":"enemy","operation":"SUM","stat":"HEALTH"},{"type":"EFFECT","effect":{"action":"SET_STAT","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"ally"},"values":{"stat":"HEALTH","amountExpression":{"kind":"RESULT_VALUE","resultId":"enemyStat"},"currentHealthOnly":true}}},{"type":"EFFECT","effect":{"action":"SET_STAT","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"enemy"},"values":{"stat":"HEALTH","amountExpression":{"kind":"RESULT_VALUE","resultId":"allyStat"},"currentHealthOnly":true}}},{"type":"EFFECT","effect":{"action":"STUN","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"ally"}}},{"type":"EFFECT","effect":{"action":"STUN","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"enemy"}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-annihilation','절멸','TECHNIQUE',6,0,0,'현재 공격력이 3 이하인 모든 선수를 DESTROY합니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"EFFECT","effect":{"action":"DESTROY","target":{"zone":"BOARD","owner":"ALL","cardType":"WRESTLER","selection":"ALL","count":1,"filter":{"attack":{"compare":"LTE","value":3}}}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-forced-exchange','강제 교환','TECHNIQUE',4,0,0,'아군 선수 1장과 상대 선수 1장을 선택하여 현재 공격력을 서로 교환합니다. 두 선수 모두 기절합니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"SELECT","id":"ally","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"SELECT","id":"enemy","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"AGGREGATE","id":"allyStat","selectionId":"ally","operation":"SUM","stat":"ATTACK"},{"type":"AGGREGATE","id":"enemyStat","selectionId":"enemy","operation":"SUM","stat":"ATTACK"},{"type":"EFFECT","effect":{"action":"SET_STAT","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"ally"},"values":{"stat":"ATTACK","amountExpression":{"kind":"RESULT_VALUE","resultId":"enemyStat"}}}},{"type":"EFFECT","effect":{"action":"SET_STAT","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"enemy"},"values":{"stat":"ATTACK","amountExpression":{"kind":"RESULT_VALUE","resultId":"allyStat"}}}},{"type":"EFFECT","effect":{"action":"STUN","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"ally"}}},{"type":"EFFECT","effect":{"action":"STUN","target":{"zone":"BOARD","owner":"ENEMY","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"enemy"}}}]}]}'::jsonb,'DRAFT'),
('epic-spell-escape','탈출','TECHNIQUE',3,0,0,'아군 선수 1장을 선택하여 원래 카드 상태로 내 손으로 되돌립니다.','EPIC','SCRIPT_V1','{"scripts":[{"version":"SCRIPT_V1","trigger":"ACTIVE","steps":[{"type":"SELECT","id":"chosen","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"PLAYER_CHOICE","count":1}},{"type":"EFFECT","effect":{"action":"MOVE_TO_HAND","target":{"zone":"BOARD","owner":"SELF","cardType":"WRESTLER","selection":"ALL","count":1,"resultId":"chosen"}}}]}]}'::jsonb,'DRAFT'),
